using Microsoft.Data.Sqlite;using System.Text.Json;using SobhanNotificationHub.Models;using SobhanNotificationHub.Services;
namespace SobhanNotificationHub.Data;public sealed class LocalCacheDb{private readonly string _connection;public LocalCacheDb(){Directory.CreateDirectory(AppSettings.DataDirectory);_connection=new SqliteConnectionStringBuilder{DataSource=Path.Combine(AppSettings.DataDirectory,"app.db"),Mode=SqliteOpenMode.ReadWriteCreate}.ToString();}private SqliteConnection Open(){var c=new SqliteConnection(_connection);c.Open();return c;}public async Task InitializeAsync(){await using var c=Open();var cmd=c.CreateCommand();cmd.CommandText="""CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY,module TEXT NOT NULL,type TEXT NOT NULL,priority TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,safe_body TEXT NOT NULL,action_url TEXT,actions_json TEXT NOT NULL,created_at TEXT NOT NULL,shown_at TEXT NOT NULL,acked INTEGER NOT NULL DEFAULT 0,read_at TEXT,clicked_at TEXT);CREATE TABLE IF NOT EXISTS state(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS idx_cache_created ON notifications(id DESC);""";await cmd.ExecuteNonQueryAsync();}public async Task<bool> ExistsAsync(long id){await using var c=Open();var cmd=c.CreateCommand();cmd.CommandText="SELECT 1 FROM notifications WHERE id=$id";cmd.Parameters.AddWithValue("$id",id);return await cmd.ExecuteScalarAsync() is not null;}public async Task SaveAsync(SobhanNotification n){await using var c=Open();var cmd=c.CreateCommand();cmd.CommandText="INSERT OR IGNORE INTO notifications(id,module,type,priority,title,body,safe_body,action_url,actions_json,created_at,shown_at) VALUES($id,$m,$t,$p,$title,$body,$safe,$url,$actions,$created,$shown);DELETE FROM notifications WHERE id NOT IN(SELECT id FROM notifications ORDER BY id DESC LIMIT 500)";cmd.Parameters.AddWithValue("$id",n.Id);cmd.Parameters.AddWithValue("$m",n.Module);cmd.Parameters.AddWithValue("$t",n.Type);cmd.Parameters.AddWithValue("$p",n.Priority);cmd.Parameters.AddWithValue("$title",n.Title);cmd.Parameters.AddWithValue("$body",n.Body);cmd.Parameters.AddWithValue("$safe",n.SafeBody);cmd.Parameters.AddWithValue("$url",(object?)n.ActionUrl??DBNull.Value);cmd.Parameters.AddWithValue("$actions",JsonSerializer.Serialize(n.Actions));cmd.Parameters.AddWithValue("$created",n.CreatedAt);cmd.Parameters.AddWithValue("$shown",DateTimeOffset.Now.ToString("O"));await cmd.ExecuteNonQueryAsync();}public async Task<long> LastIdAsync(){await using var c=Open();var cmd=c.CreateCommand();cmd.CommandText="SELECT COALESCE(MAX(id),0) FROM notifications";return Convert.ToInt64(await cmd.ExecuteScalarAsync());}public async Task MarkAckedAsync(long id){await ExecuteAsync("UPDATE notifications SET acked=1 WHERE id=$id",id);}public async Task MarkActionAsync(long id,string action){var column=action=="mark_read"?"read_at":"clicked_at";await ExecuteAsync($"UPDATE notifications SET {column}=$now WHERE id=$id",id,true);}private async Task ExecuteAsync(string sql,long id,bool time=false){await using var c=Open();var cmd=c.CreateCommand();cmd.CommandText=sql;cmd.Parameters.AddWithValue("$id",id);if(time)cmd.Parameters.AddWithValue("$now",DateTimeOffset.Now.ToString("O"));await cmd.ExecuteNonQueryAsync();}public async Task<List<CachedNotification>> HistoryAsync(string? module=null,bool unread=false){await using var c=Open();var cmd=c.CreateCommand();cmd.CommandText="SELECT id,module,type,priority,title,safe_body,action_url,created_at,read_at FROM notifications WHERE ($module='' OR module=$module) AND ($unread=0 OR read_at IS NULL) ORDER BY id DESC LIMIT 500";cmd.Parameters.AddWithValue("$module",module??"");cmd.Parameters.AddWithValue("$unread",unread?1:0);var list=new List<CachedNotification>();await using var r=await cmd.ExecuteReaderAsync();while(await r.ReadAsync())list.Add(new(r.GetInt64(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetString(5),r.IsDBNull(6)?null:r.GetString(6),r.GetString(7),r.IsDBNull(8)?null:r.GetString(8)));return list;}}
public sealed record CachedNotification(long Id,string Module,string Type,string Priority,string Title,string Body,string? ActionUrl,string CreatedAt,string? ReadAt);
